import { ComponentType } from 'react'

export interface Example {
	title: string
	path: string
	codeUrl: string
	category: Category
	priority: number
	keywords: string[]
	multiplayer: boolean
	loadComponent(): Promise<ComponentType<{ roomId?: string }>>
	loadContent(): Promise<{ description: string; details: string }>
}

const categories = [
	['getting-started', 'Getting started'],
	['configuration', 'Configuration'],
	['editor-api', 'Editor API'],
	['ui', 'UI & theming'],
	['layout', 'Page layout'],
	['events', 'Events & effects'],
	['shapes/tools', 'Shapes & tools'],
	['users', 'Users'],
	['collaboration', 'Collaboration'],
	['data/assets', 'Data & assets'],
	['use-cases', 'Use cases'],
] as const

type Category = (typeof categories)[number][0]

interface ExampleMetaModule {
	meta: Omit<Example, 'loadComponent' | 'loadContent'>
	loadComponent(): Promise<ComponentType<{ roomId?: string }>>
	loadContent(): Promise<{ description: string; details: string }>
}

const allExamples = Object.values(
	import.meta.glob('./examples/**/README.md', { eager: true })
) as ExampleMetaModule[]

const categorySet = new Set(categories.map(([category]) => category))

const sortedExamples = allExamples
	.map((module) => ({
		...module.meta,
		loadComponent: module.loadComponent,
		loadContent: module.loadContent,
	}))
	.map((example) => {
		if (!categorySet.has(example.category)) {
			throw new Error(`Unknown category "${example.category}" for example "${example.title}"`)
		}
		return example
	})

const getExamplesForCategory = (category: Category) =>
	sortedExamples
		.filter((e) => e.category === category)
		.sort((a, b) => {
			if (a.priority === b.priority) return a.title.localeCompare(b.title)
			return a.priority - b.priority
		})

export const examples = categories.map(([category, title]) => ({
	id: title,
	value: getExamplesForCategory(category as Category),
}))

import { getAssetUrlsByMetaUrl } from '@tldraw/assets/urls'
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { Helmet, HelmetProvider } from 'react-helmet-async'
import { RouterProvider, createBrowserRouter } from 'react-router-dom'
import {
	DefaultErrorFallback,
	ErrorBoundary,
	setDefaultEditorAssetUrls,
	setDefaultUiAssetUrls,
} from 'tldraw'
import { ExamplePage } from './ExamplePage'
import { examples } from './examples'
import { ExampleWrapper } from './ExampleWrapper'
import Develop from './misc/develop'
import EndToEnd from './misc/end-to-end'

const ENABLE_STRICT_MODE = false

// we use secret internal `setDefaultAssetUrls` functions to set these at the
// top-level so assets don't need to be passed down in every single example.
const assetUrls = getAssetUrlsByMetaUrl()
setDefaultEditorAssetUrls(assetUrls)
setDefaultUiAssetUrls(assetUrls)
const gettingStartedExamples = examples.find((e) => e.id === 'Getting started')
if (!gettingStartedExamples) throw new Error('Could not find getting started examples')
const basicExample = gettingStartedExamples.value[0]
if (!basicExample) throw new Error('Could not find initial example')

const router = createBrowserRouter([
	{
		path: '*',
		lazy: async () => ({ element: <div>404</div> }),
	},
	{
		path: '/',
		lazy: async () => {
			const Component = await basicExample.loadComponent()
			return {
				element: (
					<ExamplePage example={basicExample}>
						<ExampleWrapper example={basicExample} component={Component} />
					</ExamplePage>
				),
			}
		},
	},
	{
		path: 'develop',
		lazy: async () => ({ element: <Develop /> }),
	},
	{
		path: 'end-to-end',
		lazy: async () => ({ element: <EndToEnd /> }),
	},
	...examples.flatMap((exampleArray) =>
		exampleArray.value.flatMap((example) => [
			{
				path: example.path,
				lazy: async () => {
					const Component = await example.loadComponent()
					return {
						element: (
							<NoIndex>
								<ExamplePage example={example}>
									<ExampleWrapper example={example} component={Component} />
								</ExamplePage>
							</NoIndex>
						),
					}
				},
			},
			{
				path: `${example.path}/full`,
				lazy: async () => {
					const Component = await example.loadComponent()
					return {
						element: (
							<NoIndex>
								<ExampleWrapper example={example} component={Component} />
							</NoIndex>
						),
					}
				},
			},
		])
	),
])

function NoIndex({ children }: { children: React.ReactNode }) {
	return (
		<>
			<Helmet>
				<meta name="robots" content="noindex, noimageindex, nofollow" />
			</Helmet>
			{children}
		</>
	)
}

document.addEventListener('DOMContentLoaded', () => {
	const rootElement = document.getElementById('root')!
	const root = createRoot(rootElement!)
	const main = (
		<ErrorBoundary
			fallback={(error) => <DefaultErrorFallback error={error} />}
			onError={(error) => console.error(error)}
		>
			<HelmetProvider>
				<RootMeta />
				<RouterProvider router={router} />
			</HelmetProvider>
		</ErrorBoundary>
	)
	root.render(ENABLE_STRICT_MODE ? <StrictMode>{main}</StrictMode> : main)
})

function RootMeta() {
	return (
		<Helmet>
			<title>tldraw examples</title>
			<meta
				name="keywords"
				content="tldraw, examples, whiteboard, react, collaborative whiteboard, online drawing, team collboration, react, library"
			/>
			<meta
				name="description"
				content="Examples for using tldraw - a library for building infinite canvases with React. "
			/>
		</Helmet>
	)
}

import { AlertDialog as _AlertDialog } from 'radix-ui'
import { Dispatch, createContext, useContext, useEffect, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import tldrawSdkLogoLight from '../../../assets/tldraw_sdk_logo_light.png'
import { Example, examples } from './examples'

const dialogContext = createContext<{
	example: Example | null
	setExampleDialog: Dispatch<Example | null>
}>({
	example: null,
	setExampleDialog: () => void null,
})

export function DialogContextProvider({ children }: { children: React.ReactNode }) {
	const [example, setExampleDialog] = useState<Example | null>(null)
	return (
		<dialogContext.Provider value={{ example, setExampleDialog }}>
			{children}
		</dialogContext.Provider>
	)
}

export function ExamplePage({
	example,
	children,
}: {
	example: Example
	children: React.ReactNode
}) {
	const categories = examples.map((e) => e.id)
	const [filterValue, setFilterValue] = useState('')
	const searchTerms = getSearchTerms(filterValue)
	const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		setFilterValue(e.target.value)
		history.replaceState(
			{},
			'',
			e.target.value ? `/?filter=${encodeURIComponent(e.target.value)}` : '/'
		)
	}

	useEffect(() => {
		const urlParams = new URLSearchParams(window.location.search)
		const filter = urlParams.get('filter')
		if (filter) {
			setFilterValue(decodeURIComponent(filter))
		}
	}, [])

	return (
		<DialogContextProvider>
			<div className="example">
				<nav className="example__sidebar scroll-light">
					<div className="example__sidebar__top">
						<div className="example__sidebar__header">
							<Link className="example__sidebar__header__logo" to="/" aria-label="tldraw examples">
								<TldrawLogo />
							</Link>
							<span className="example__sidebar__header-title">Examples</span>
							<Link
								to={`${example.path}/full`}
								className="example__sidebar__item__button hoverable hoverable__small"
								aria-label="Collapse sidebar"
								title="Collapse sidebar"
							>
								<CollapseSidebarIcon />
							</Link>
						</div>
						<div className="example__sidebar__section">
							<label className="example__sidebar__search hoverable">
								<SearchIcon />
								<input
									className="example__sidebar__filter"
									id="example-sidebar-filter"
									name="filter"
									aria-label="Search examples"
									placeholder="Search..."
									value={filterValue}
									onChange={handleFilterChange}
								/>
							</label>
							<a className="example__sidebar__action-row hoverable" href="/develop">
								<CodeIcon />
								<span>Develop</span>
							</a>
						</div>
						<div className="example__sidebar__divider" />
					</div>
					<ul className="example__sidebar__categories">
						{categories.map((currentCategory) => (
							<li key={currentCategory} className="example__sidebar__category">
								<h3 className="example__sidebar__category__header">{currentCategory}</h3>
								<ul className="example__sidebar__category__items">
									{examples
										.find((category) => category.id === currentCategory)
										?.value.filter((example) => {
											return exampleMatchesSearch(example, searchTerms)
										})
										.map((sidebarExample) => (
											<ExampleSidebarListItem
												key={sidebarExample.path}
												example={sidebarExample}
												isActive={sidebarExample.path === example.path}
												searchTerms={searchTerms}
											/>
										))}
								</ul>
							</li>
						))}
					</ul>
					<div className="example__sidebar__footer-links">
						<a className="example__sidebar__footer-link hoverable" href="/develop">
							<CodeIcon />
							<span>Build with the tldraw SDK</span>
						</a>
						<a
							className="example__sidebar__footer-link hoverable hoverable__small"
							target="_blank"
							rel="noopener noreferrer"
