import { getLicenseKey } from '@tldraw/dotcom-shared'
import { createMermaidDiagram } from '@tldraw/mermaid'
import { useEffect, useLayoutEffect } from 'react'
import {
	BaseBoxShapeUtil,
	Editor,
	TLShape,
	Tldraw,
	VecModel,
	allDefaultFontFaces,
	b64Vecs,
	createShapeId,
	exportAs,
	getArrowInfo,
	mockUniqueId,
	toRichText,
	useActions,
	useEditor,
	useUniqueSafeId,
} from 'tldraw'
import 'tldraw/tldraw.css'
import { EndToEndApi } from './EndToEndApi'
;(window as any).__tldraw_ui_event = { id: 'NOTHING_YET' }
;(window as any).__tldraw_editor_events = []

const HTML_TYPE = 'html' as const
let nextMockShapeId = 0

declare module 'tldraw' {
	export interface TLGlobalShapePropsMap {
		[HTML_TYPE]: { html: string; css: string; w: number; h: number }
	}
}

type HtmlCssShape = TLShape<typeof HTML_TYPE>
class HtmlCssShapeUtil extends BaseBoxShapeUtil<HtmlCssShape> {
	static override type = HTML_TYPE

	override getDefaultProps(): { html: string; css: string; w: number; h: number } {
		return { w: 100, h: 100, html: '', css: '' }
	}
	override component(shape: HtmlCssShape) {
		return <HtmlCssShapeComponent shape={shape} />
	}
	override getIndicatorPath(shape: HtmlCssShape) {
		const path = new Path2D()
		path.rect(0, 0, shape.props.w, shape.props.h)
		return path
	}
}
function HtmlCssShapeComponent({ shape }: { shape: HtmlCssShape }) {
	const id = useUniqueSafeId()

	useLayoutEffect(() => {
		const style = document.createElement('style')
		// tests can use #self in their CSS to refer uniquely to this shape so we can test how well
		// CSS in <head> is applied to the shape when exporting.
		style.textContent = shape.props.css.replace(/#self/g, `#${id}`)
		document.head.appendChild(style)
		return () => {
			document.head.removeChild(style)
		}
	}, [shape.props.css, id])

	return <div id={id} dangerouslySetInnerHTML={{ __html: shape.props.html }} />
}

export default function EndToEnd() {
	// Use test license key if available, otherwise use the default
	// Check if __TLDRAW_LICENSE_KEY__ was explicitly set (including null/undefined/empty string)
	const testLicenseKey = (window as any).__TLDRAW_LICENSE_KEY__
	const hasExplicitTestKey = Object.prototype.hasOwnProperty.call(window, '__TLDRAW_LICENSE_KEY__')
	const licenseKey = hasExplicitTestKey ? testLicenseKey : getLicenseKey()

	useLayoutEffect(() => {
		if (customElements.get('custom-element')) return

		const template = document.createElement('template')
		template.innerHTML = `
			<style>
				article {
					margin: 1em;
					display: flex;
					flex-direction: column;
					gap: 1em;
				}
				.list {
					background-color: lightskyblue;
					padding: 1em;
				}
				.choice {
					background-color: lightgreen;
					padding: 1em;
				}
			</style>
			<article>
				<div class="list">
					list: <slot name="list"></slot>
				</div>
				<div class="choice">
					choice: <slot name="choice"></slot>
				</div>
			</article>
		`
		customElements.define(
			'custom-element',
			class extends HTMLElement {
				constructor() {
					super()
					const templateContent = template.content
					const shadowRoot = this.attachShadow({ mode: 'open' })
					shadowRoot.appendChild(templateContent.cloneNode(true))
				}
			}
		)
	}, [])

	return (
		<div className="tldraw__editor">
			<Tldraw
				licenseKey={licenseKey}
				onMount={(editor) => {
					;(window as any).app = editor
					;(window as any).editor = editor

					editor.on('event', (info) => {
						;(window as any).__tldraw_editor_events.push(info)
					})
				}}
				onUiEvent={(name, data) => {
					;(window as any).__tldraw_ui_event = { name, data }
				}}
				shapeUtils={[HtmlCssShapeUtil]}
			>
				<SneakyExportButton />
			</Tldraw>
		</div>
	)
}

function SneakyExportButton() {
	const editor = useEditor()
	const actions = useActions()

	useEffect(() => {
		const resetMockShapeIds = () => {
			nextMockShapeId = 0
			mockUniqueId(() => `mock-${nextMockShapeId++}`)
		}

		const api: EndToEndApi = {
			exportAsSvg: () => actions['export-as-svg'].onSelect('unknown'),
			exportAsFormat: (format) =>
				exportAs(editor, editor.selectAll().getSelectedShapeIds(), { format, name: 'test' }),
			createShapeId: () => createShapeId(),
			resetMockShapeIds,
			createMermaidDiagram: async (definition: string) => {
				await createMermaidDiagram(editor, definition, {
					blueprintRender: {
						position: { x: 0, y: 0 },
						centerOnPosition: false,
					},
				})
			},
			toRichText: (text: string) => toRichText(text),
			preloadFonts: async () => {
				// Load every default font face up front. Text geometry is measured from the
				// loaded font, so anything that measures a shape before its font loads (e.g.
				// laying out shapes by their measured bounds) would otherwise get fallback-font
				// metrics until the real font swaps in.
				await Promise.all(allDefaultFontFaces.map((font) => editor.fonts.ensureFontIsLoaded(font)))
			},
			b64VecsEncodePoints: (points: VecModel[]) => b64Vecs.encodePoints(points),
			markAllArrowBindings: () => {
				for (const shape of editor.getCurrentPageShapes()) {
					if (!editor.isShapeOfType(shape, 'arrow')) continue

					const info = getArrowInfo(editor, shape)
					if (!info) continue

					const transform = editor.getShapePageTransform(shape.id)

					if (info.bindings.start) {
						createArrowBindingMarker(editor, transform.applyToPoint(info.start.handle))
					}

					if (info.bindings.end) {
						createArrowBindingMarker(editor, transform.applyToPoint(info.end.handle))
					}
				}
			},
		}
		;(window as any).tldrawApi = api
	}, [actions, editor])

	return null
}

function createArrowBindingMarker(editor: Editor, pagePoint: VecModel) {
	const markRadius = 3
	editor.createShape({
		type: 'geo',
		x: pagePoint.x - markRadius,
		y: pagePoint.y - markRadius,
		props: {
			geo: 'ellipse',
			w: markRadius * 2,
			h: markRadius * 2,
			color: 'light-blue',
			fill: 'none',
			dash: 'solid',
			size: 's',
		},
	})
}

import { getLicenseKey } from '@tldraw/dotcom-shared'
import {
	DefaultContextMenu,
	DefaultContextMenuContent,
	DefaultDebugMenu,
	DefaultDebugMenuContent,
	ExampleDialog,
	PerformanceApiAdapter,
	TLComponents,
	Tldraw,
	TldrawUiMenuActionCheckboxItem,
	TldrawUiMenuActionItem,
	TldrawUiMenuGroup,
	TldrawUiMenuItem,
	track,
	useDialogs,
	useEditor,
} from 'tldraw'
import 'tldraw/tldraw.css'
import { trackedShapes, useDebugging } from '../hooks/useDebugging'
import { usePerformance } from '../hooks/usePerformance'
import { A11yResultTable } from './a11y'
import { getDiff } from './diff'

const ContextMenu = track(() => {
	const editor = useEditor()
	const oneShape = editor.getOnlySelectedShape()
	const selectedShapes = editor.getSelectedShapes()
	const tracked = trackedShapes.get()

	return (
		<DefaultContextMenu>
			<DefaultContextMenuContent />
			{selectedShapes.length > 0 && (
				<TldrawUiMenuGroup id="debugging">
					<TldrawUiMenuActionItem actionId="log-shapes" />
					{oneShape && (
						<TldrawUiMenuActionCheckboxItem
							checked={tracked.includes(oneShape.id)}
							actionId="track-changes"
						/>
					)}
				</TldrawUiMenuGroup>
			)}
		</DefaultContextMenu>
	)
})

function A11yAudit() {
	const { addDialog } = useDialogs()

	const runA11yAudit = async () => {
		const axe = (await import('axe-core')).default
		axe.run(document, {}, (err, results) => {
			if (err) throw err

			// eslint-disable-next-line no-console
			console.debug('[a11y]:', results)

			addDialog({
				component: ({ onClose }) => (
					<ExampleDialog
						body={<A11yResultTable results={results} />}
						title="Accessibility Audit Results"
						maxWidth="80vw"
						cancel="Close"
						confirm="Ok"
						onCancel={() => onClose()}
						onContinue={() => onClose()}
					/>
				),
				onClose: () => {
					void null
				},
			})
		})
	}

	return <TldrawUiMenuItem id="a11y-audit" onSelect={runA11yAudit} label={'A11y audit'} />
}

const components: TLComponents = {
	ContextMenu,
	DebugMenu: () => (
		<DefaultDebugMenu>
			<A11yAudit />
			<DefaultDebugMenuContent />
		</DefaultDebugMenu>
	),
}

function afterChangeHandler(prev: any, next: any) {
	const tracked = trackedShapes.get()
	if (tracked.includes(next.id)) {
		// eslint-disable-next-line no-console
		console.table(getDiff(prev, next))
	}
}

export default function Develop() {
	const performanceOverrides = usePerformance()
	const debuggingOverrides = useDebugging()

	return (
		<div className="tldraw__editor">
			<Tldraw
				licenseKey={getLicenseKey()}
				overrides={[performanceOverrides, debuggingOverrides]}
				persistenceKey="example"
				onMount={(editor) => {
					;(window as any).app = editor
					;(window as any).editor = editor

					Object.defineProperty(window, '$s', {
						get: function () {
							return editor.getOnlySelectedShape()
						},
						configurable: true,
						enumerable: true,
					})

					const dispose = editor.store.sideEffects.registerAfterChangeHandler(
						'shape',
						afterChangeHandler
					)

					const perfAdapter = new PerformanceApiAdapter(editor.performance)

					return () => {
						dispose()
						perfAdapter.dispose()
					}
				}}
				components={components}
			></Tldraw>
		</div>
	)
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { uniqueId } from 'tldraw'
import { Example } from './examples'

export function ExampleWrapper({
	example,
	component: Component,
}: {
	example: Example
	component: React.ComponentType<{ roomId?: string }>
}) {
	if (!example.multiplayer) {
		return <Component />
	}

	return <MultiplayerExampleWrapper component={Component} example={example} />
}

interface ScopedRoomId {
	roomId: string
	deployId: string
}

function getExampleKey(exampleSlug: string) {
	return `tldraw-example-room-${exampleSlug}`
}

function getRoomId(exampleSlug: string) {
	const key = getExampleKey(exampleSlug)
	const stored = JSON.parse(localStorage.getItem(key) ?? 'null') as null | ScopedRoomId
	if (stored && stored.deployId === process.env.TLDRAW_DEPLOY_ID) {
		return stored.roomId
	}
	return uniqueId()
}

function storeRoomId(exampleSlug: string, slug: string) {
	const key = getExampleKey(exampleSlug)
	localStorage.setItem(
		key,
		JSON.stringify({
			roomId: slug,
			deployId: process.env.TLDRAW_DEPLOY_ID!,
		} satisfies ScopedRoomId)
	)
}

function useConfirmState() {
	const [confirm, setConfirm] = useState(false)
	const confirmTimeout = useRef<number | null>(null)

	const confirmFn = useCallback(() => {
		if (confirmTimeout.current) {
			clearTimeout(confirmTimeout.current)
		}
		setConfirm(true)
		confirmTimeout.current = window.setTimeout(() => {
			setConfirm(false)
			confirmTimeout.current = null
		}, 3000)
	}, [])

	useEffect(() => {
		return () => {
			if (confirmTimeout.current) {
				clearTimeout(confirmTimeout.current)
			}
		}
	}, [])

	return [confirm, confirmFn] as const
}

function MultiplayerExampleWrapper({
	component: Component,
	example,
}: {
	example: Example
	component: React.ComponentType<{ roomId?: string }>
}) {
	const [params, setParams] = useSearchParams()
	const [confirm, confirmFn] = useConfirmState()
	const exampleSlug = example.path.replace(/^\/?/g, '')
	const roomIdParam = params.get('roomId')
	let roomId = roomIdParam
	if (!roomId || typeof roomId !== 'string' || encodeURIComponent(roomId) !== roomId) {
		roomId = getRoomId(exampleSlug)
	}

	useEffect(() => {
		if (roomId === roomIdParam) return
		storeRoomId(exampleSlug, roomId)
		const nextParams = new URLSearchParams(params)
		nextParams.set('roomId', roomId)
		setParams(nextParams, { replace: true })
	}, [exampleSlug, roomId, roomIdParam, setParams, params])

	return (
		<div className="MultiplayerExampleWrapper">
			<div className="MultiplayerExampleWrapper-picker">
				<WifiIcon />
				<div>Live Example</div>
				<button
					className="MultiplayerExampleWrapper-copy"
					onClick={() => {
						// copy current url with roomId=roomId to clipboard
						const url = new URL(window.location.href)
						url.searchParams.set('roomId', roomId)
						navigator.clipboard.writeText(url.toString())
						confirmFn()
					}}
					aria-label="join"
				>
					Copy link
					{confirm && <div className="MultiplayerExampleWrapper-copied">Copied!</div>}
				</button>
			</div>
			<div className="MultiplayerExampleWrapper-example">
				<Component roomId={roomId} />
			</div>
		</div>
	)
}

function WifiIcon() {
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			fill="none"
			viewBox="0 0 24 24"
			strokeWidth="1.5"
			stroke="currentColor"
			width={16}
		>
			<path
				strokeLinecap="round"
				strokeLinejoin="round"
				d="M8.288 15.038a5.25 5.25 0 0 1 7.424 0M5.106 11.856c3.807-3.808 9.98-3.808 13.788 0M1.924 8.674c5.565-5.565 14.587-5.565 20.152 0M12.53 18.22l-.53.53-.53-.53a.75.75 0 0 1 1.06 0Z"
			/>
		</svg>
	)
}

