const __vite__css = "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@500;600;700&display=swap');

:root {
	--background: white;
	--text: hsl(0, 0%, 11%);
	--gray-light: #f5f5f5;
	--gray-dark: #e8e8e8;
	--black-transparent-lighter: rgba(0, 0, 0, 0.07);
	--black-transparent-light: rgba(0, 0, 0, 0.3);
	--black-transparent-dark: rgba(0, 0, 0, 0.5);
	--black-transparent-darker: rgba(0, 0, 0, 0.7);
	--focus: hsl(214, 84%, 56%);
	--whiteboard: hsl(210, 20%, 98%);
	--example-sidebar-width: 260px;
	--example-sidebar-bg: hsl(0, 0%, 99%);
	--example-sidebar-border: hsl(204, 16%, 94%);
	--example-sidebar-divider: hsl(0, 0%, 91%);
	--example-sidebar-text: hsl(0, 0%, 11%);
	--example-sidebar-text-muted: hsl(204, 4%, 45%);
	--example-sidebar-hover: hsl(0, 0%, 0%, 2%);
	--example-sidebar-active: hsl(0, 0%, 0%, 4.3%);
	--example-sidebar-primary: hsl(214, 84%, 56%);
	--example-content-bg: #ffffff;
	color-scheme: light;
}

html,
body {
	padding: 0;
	margin: 0;
	font-family: 'Inter', sans-serif;
	min-height: 100vh;
	/* mobile viewport bug fix */
	min-height: -webkit-fill-available;
	height: 100%;
	/* prevent two-finger swipe to go back */
	overscroll-behavior: none;
	background-color: var(--background);
	color: var(--text);
}

@media screen and (max-width: 600px) {
	html,
	body {
		font-size: 14px;
	}
}

html,
* {
	box-sizing: border-box;
}

/* NB: If we did position: fixed, Safari on iOS 18 and MacOS 15 would
 * have several rendering issues. This must stay position: absolute. */

.tldraw__editor {
	position: absolute;
	inset: 0px;
	overflow: hidden;
	overscroll-behavior: none;
	touch-action: none;
}

.example {
	position: absolute;
	inset: 0;
	display: flex;
	align-items: stretch;
	background: var(--example-content-bg);
}

.example__content {
	position: relative;
	height: 100%;
	width: 100%;
	min-width: 0;
	overflow: auto;
}

@media screen and (max-width: 700px) {
	.example {
		display: flex;
	}

	.example__sidebar {
		display: none;
	}

	.example__content {
		height: 100%;
	}
}

/* --------------------- Sidebar -------------------- */

.example__sidebar {
	width: var(--example-sidebar-width);
	min-width: var(--example-sidebar-width);
	display: flex;
	flex-direction: column;
	flex: 0 0 auto;
	padding: 0 0 4px 0;
	background: var(--example-sidebar-bg);
	border-right: 1px solid var(--example-sidebar-border);
	overflow: hidden;
	color: var(--example-sidebar-text);
	font-size: 12px;
	font-weight: 500;
	line-height: 1.3;
	max-height: 100vh;
}

.example__sidebar a {
	text-decoration: none;
	color: inherit;
}

/* Header */

.example__sidebar__top {
	flex: 0 0 auto;
}

.example__sidebar__header {
	display: flex;
	height: 44px;
	align-items: center;
	padding: 0px 8px 3px 4px;
	gap: 12px;
}

.example__sidebar__header__logo {
	all: unset;
	cursor: pointer;
	flex: none;
	display: flex;
	align-items: center;
	justify-content: flex-start;
	overflow: hidden;
	height: 40px;
	flex-grow: 2;
	padding-right: 6px;
	padding-left: 12px;
	padding-bottom: 1px;
}

.examples__tldraw__logo {
	flex-shrink: 0;
	display: block;
	width: auto;
	height: 19px;
	object-fit: contain;
	object-position: left center;
	pointer-events: none;
	user-select: none;
}

.example__sidebar__header-title {
	display: none;
}

.example__sidebar__section {
	display: flex;
	flex-direction: column;
	flex: 0 0 auto;
	justify-content: center;
	padding: 6px 12px;
}

.example__sidebar__divider {
	height: 8px;
	margin: 0 12px;
	display: flex;
	align-items: center;
	flex: 0 0 auto;
}

.example__sidebar__divider::after {
	content: '';
	width: 100%;
	height: 1px;
	background-color: var(--example-sidebar-divider);
}

.example__sidebar__search {
	position: relative;
	display: flex;
	align-items: center;
	gap: 6px;
	height: 36px;
	width: 100%;
	padding: 0 4px 0 8px;
	color: var(--example-sidebar-text);
}

.example__sidebar__search::before {
	content: '';
	position: absolute;
	inset: 2px 0;
	border-radius: 4px;
	border: 1px solid transparent;
	pointer-events: none;
}

.example__sidebar__search:focus-within {
	outline: none;
}

.example__sidebar__search:focus-within::before {
	border-color: var(--example-sidebar-primary);
}

.example__sidebar__search > svg {
	position: relative;
	z-index: 1;
	flex: 0 0 auto;
	width: 15px;
	height: 15px;
	color: var(--example-sidebar-text);
}

.example__sidebar__filter {
	all: unset;
	flex: 1 1 auto;
	min-width: 0;
	height: 100%;
	color: var(--example-sidebar-text);
	font-size: 12px;
	font-weight: 500;
	line-height: 1.3;
	position: relative;
	z-index: 1;
}

.example__sidebar__filter::placeholder {
	color: var(--example-sidebar-text);
	opacity: 1;
}

.example__sidebar__action-row,
.example__sidebar__footer-link {
	position: relative;
	display: flex;
	flex-direction: row;
	align-items: center;
	gap: 6px;
	height: 36px;
	flex: 0 0 auto;
	background: none;
	border: none;
	cursor: pointer;
	color: var(--example-sidebar-text);
	padding: 0 8px;
	text-align: left;
	text-decoration: none;
	border-radius: 0;
	white-space: nowrap;
}

.example__sidebar__action-row > svg,
.example__sidebar__footer-link > svg {
	flex: 0 0 auto;
