	flex-direction: column;
	position: relative;
	flex: 0 0 auto;
	padding: 6px 12px 0 12px;
}

.example__sidebar__footer-links::before {
	content: '';
	position: absolute;
	top: 0;
	left: 12px;
	right: 12px;
	height: 1px;
	background: var(--example-sidebar-divider);
}

/* --------------------- Scroll --------------------- */

.scroll-light {
	scrollbar-width: thin;
}

.scroll-light::-webkit-scrollbar {
	display: block;
	width: 8px;
	height: 8px;
	position: absolute;
	top: 0;
	left: 0;
	background-color: inherit;
}

.scroll-light::-webkit-scrollbar-button {
	display: none;
	width: 0;
	height: 10px;
}

.scroll-light::-webkit-scrollbar-thumb {
	background-clip: padding-box;
	width: 0;
	min-height: 36px;
	border: 2px solid transparent;
	border-radius: 6px;
	background-color: var(--black-transparent-light);
}

.scroll-light::-webkit-scrollbar-thumb:hover {
	background-color: var(--black-transparent-light);
}

/* ---------------------- Hover --------------------- */

.hoverable::after {
	display: block;
	content: '';
	position: absolute;
	top: 2px;
	left: 0;
	right: 0;
	bottom: 2px;
	visibility: hidden;
	z-index: 0;
	background-color: var(--example-sidebar-hover);
	border-radius: 4px;
	pointer-events: none;
}

.hoverable > svg {
	position: relative;
	z-index: 1;
}

@media (hover: hover) {
	.hoverable:hover::after {
		visibility: visible;
	}
}

.hoverable__small::after {
	inset: 4px;
	border-radius: 4px;
}

/* --------------------- Dialog --------------------- */

.example__dialog__overlay {
	position: fixed;
	inset: 0;
	z-index: 9999999998;
	background-color: hsl(0, 0%, 0%, 20%);
}

.example__dialog__content {
	cursor: default;
	position: fixed;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	z-index: 9999999999;
	display: flex;
	flex-direction: column;
	width: 420px;
	min-width: 300px;
	max-width: calc(100vw - 48px);
	max-height: 80vh;
	overflow: hidden;
	border-radius: 9px;
	box-shadow:
		0px 1px 2px hsl(0, 0%, 0%, 28%),
		0px 2px 6px hsl(0, 0%, 0%, 14%),
		inset 0px 0px 0px 1px hsl(0, 0%, 100%);
	padding: 0;
	background-color: hsl(0, 0%, 99%);
	color: hsl(0, 0%, 18%);
	font-size: 12px;
}

.example__dialog__header {
	position: relative;
	display: flex;
	align-items: center;
	flex: 0 0 auto;
	min-height: 40px;
	padding: 0 0 0 12px;
	color: hsl(0, 0%, 18%);
}

.example__dialog__title {
	flex: 1 1 auto;
	margin: 0;
	font-size: 12px;
	font-weight: 500;
	line-height: inherit;
	color: hsl(0, 0%, 18%);
}

.example__dialog__header__close {
	all: unset;
	position: relative;
	cursor: pointer;
	width: 40px;
	height: 40px;
	display: flex;
	flex: 0 0 auto;
	align-items: center;
	justify-content: center;
	color: hsl(0, 0%, 18%);
}

.example__dialog__header__close::after {
	content: '';
	position: absolute;
	inset: 4px;
	border-radius: 4px;
	background: hsl(0, 0%, 0%, 4.3%);
	opacity: 0;
	pointer-events: none;
}

.example__dialog__header__close > * {
	position: relative;
	z-index: 1;
}

@media (hover: hover) {
	.example__dialog__header__close:hover::after {
		opacity: 1;
	}
}

.example__dialog__body {
	flex: 0 1 auto;
	min-height: 0;
	overflow-y: auto;
	overflow-x: hidden;
	max-width: 100%;
	padding: 12px;
	color: hsl(0, 0%, 18%);
	user-select: text;
	-webkit-user-select: text;
}

.example__dialog__markdown {
	font-size: 12px;
	line-height: 1.6;
}

.example__dialog__markdown p {
	margin: 0 0 12px 0;
}

.example__dialog__markdown p:last-child {
	margin-bottom: 0;
}

.example__dialog__markdown a {
	color: hsl(214, 84%, 56%);
	text-decoration: none;
}

.example__dialog__markdown a:hover {
	text-decoration: underline;
}

.example__dialog__actions {
	display: flex;
	align-items: center;
	justify-content: space-between;
	min-height: 12px;
	padding: 0 0px 0px 0px;
	flex-shrink: 0;
	gap: 0;
}

.example__dialog__actions a,
.example__dialog__actions button {
	position: relative;
	cursor: pointer;
	min-width: 40px;
	height: 40px;
	padding: 0 12px;
	border-radius: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	text-decoration: none;
	gap: 6px;
	background: transparent;
	color: hsl(0, 0%, 18%);
	border: 0;
	font: inherit;
	line-height: inherit;
}

.example__dialog__actions a::after,
.example__dialog__actions button::after {
	content: '';
	position: absolute;
	inset: 4px;
	border-radius: 4px;
	background: hsl(0, 0%, 0%, 4.3%);
	opacity: 0;
	pointer-events: none;
}

@media (hover: hover) {
	.example__dialog__actions a:hover::after,
	.example__dialog__actions button:hover::after {
		opacity: 1;
	}
}

.example__dialog__actions a > *,
.example__dialog__actions button > * {
	position: relative;
	z-index: 1;
}

.example__dialog__content p > code {
	font-size: 12px;
	font-family: monospace;
	padding: 1px 3px;
	margin: 0px -2px;
	background-color: var(--black-transparent-lighter);
	border-radius: 4px;
}

.example__dialog__close {
	all: unset;
}

:root:has(.tl-theme__dark) .MultiplayerExampleWrapper {
	--background: black;
	--text: hsl(0, 9%, 94%);
	--gray-light: #333;
	--gray-dark: #444;
	--black-transparent-lighter: rgba(255, 255, 255, 0.15);
	--black-transparent-light: rgba(255, 255, 255, 0.4);
	--black-transparent-dark: rgba(255, 255, 255, 0.6);
	--black-transparent-darker: rgba(255, 255, 255, 0.7);
	--focus: hsl(217, 89%, 61%);
	--whiteboard: hsl(240, 5%, 6.5%);
	color-scheme: dark;
}

.MultiplayerExampleWrapper {
	display: flex;
	flex-direction: column;
	/* container: example / size; */
	position: absolute;
	inset: 0px;
}

.MultiplayerExampleWrapper-picker {
	display: flex;
	flex-direction: row;
	justify-content: flex-start;
	align-items: center;
	padding: 8px 16px;
	gap: 16px;
	background: var(--background);
	border-bottom: 1px solid var(--gray-dark);
	color: var(--text);
	font-size: 14px;
}

.MultiplayerExampleWrapper-copy {
	background: var(--black-transparent-lighter);
	border: 1px solid var(--gray-dark);
	border-radius: 4px;
	padding: 4px 12px;
	height: 24px;
	cursor: pointer;
	position: relative;
	text-align: center;
}

.MultiplayerExampleWrapper-copy:has(.MultiplayerExampleWrapper-copied) {
	color: transparent;
}

.MultiplayerExampleWrapper-copied {
	color: var(--text);
	position: absolute;
	inset: 0;
	display: flex;
	align-items: center;
	justify-content: center;
}

.MultiplayerExampleWrapper-copy:hover {
	border: 1px solid var(--black-transparent-lighter);
}

.MultiplayerExampleWrapper-example {
	position: relative;
	flex: 1;
}
